-- Fase 37: Logística independiente. No altera Nómina, Operación ni catálogos maestros.
CREATE TABLE IF NOT EXISTS logistica_bodegas (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), nombre text NOT NULL, codigo text NOT NULL, ubicacion text, responsable text, activo boolean NOT NULL DEFAULT TRUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(empresa_id,codigo));
CREATE TABLE IF NOT EXISTS logistica_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), codigo text, nombre text NOT NULL, categoria text NOT NULL CHECK (categoria IN ('DOTACION','EPP','DOCUMENTOS','EXTINTORES','OTROS')), unidad text NOT NULL DEFAULT 'UNIDAD', talla text, minimo numeric(12,2) NOT NULL DEFAULT 0, cantidad_por_persona boolean NOT NULL DEFAULT FALSE, activo boolean NOT NULL DEFAULT TRUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(empresa_id,codigo));
ALTER TABLE IF EXISTS logistica_items ADD COLUMN IF NOT EXISTS cantidad_por_persona boolean NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS logistica_inventario (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), bodega_id bigint NOT NULL REFERENCES logistica_bodegas(id), item_id bigint NOT NULL REFERENCES logistica_items(id), stock numeric(12,2) NOT NULL DEFAULT 0, reservado numeric(12,2) NOT NULL DEFAULT 0, updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(bodega_id,item_id));
CREATE TABLE IF NOT EXISTS logistica_rutas (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), nombre text NOT NULL, dia text, conductor text, vehiculo text, estado text NOT NULL DEFAULT 'ACTIVA', activo boolean NOT NULL DEFAULT TRUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logistica_remisiones (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), contrato_id bigint REFERENCES contratos(id), municipio_id bigint REFERENCES municipios(id), institucion_id bigint REFERENCES instituciones(id), sede_id bigint REFERENCES sedes(id), vinculacion_id bigint REFERENCES vinculaciones(id), ruta_id bigint REFERENCES logistica_rutas(id), bodega_origen_id bigint REFERENCES logistica_bodegas(id), numero_remision text NOT NULL, fecha date NOT NULL DEFAULT CURRENT_DATE, fecha_salida timestamp, estado text NOT NULL DEFAULT 'BORRADOR' CHECK (estado IN ('BORRADOR','PREPARADA','DESPACHADA','EN_RUTA','RECIBIDA','CON_NOVEDAD','CERRADA','ANULADA')), observacion text, created_by bigint REFERENCES usuarios(id), created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(empresa_id,numero_remision));
CREATE TABLE IF NOT EXISTS logistica_remision_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, remision_id bigint NOT NULL REFERENCES logistica_remisiones(id) ON DELETE CASCADE, item_id bigint NOT NULL REFERENCES logistica_items(id), cantidad numeric(12,2) NOT NULL CHECK(cantidad>0), valor_unitario numeric(14,2), destino_tipo text NOT NULL DEFAULT 'SEDE', destino_vinculacion_id bigint REFERENCES vinculaciones(id), created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logistica_recepciones (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, remision_id bigint NOT NULL REFERENCES logistica_remisiones(id), receptor text, fecha_hora timestamp NOT NULL DEFAULT now(), observacion text, evidencia_path text, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logistica_novedades (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, remision_id bigint NOT NULL REFERENCES logistica_remisiones(id), tipo text NOT NULL, descripcion text NOT NULL, created_by bigint REFERENCES usuarios(id), created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logistica_conductores (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), nombre text NOT NULL, documento text, telefono text, activo boolean NOT NULL DEFAULT TRUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS logistica_vehiculos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), placa text NOT NULL, tipo text, propietario_empresa text, activo boolean NOT NULL DEFAULT TRUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(empresa_id,placa));
CREATE TABLE IF NOT EXISTS logistica_movimientos (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, empresa_id bigint NOT NULL REFERENCES empresas(id), item_id bigint NOT NULL REFERENCES logistica_items(id), bodega_origen_id bigint REFERENCES logistica_bodegas(id), bodega_destino_id bigint REFERENCES logistica_bodegas(id), remision_id bigint REFERENCES logistica_remisiones(id), tipo text NOT NULL CHECK(tipo IN ('ENTRADA','SALIDA','AJUSTE','TRASLADO','RESERVA','LIBERACION')), cantidad numeric(12,2) NOT NULL CHECK(cantidad>0), motivo text, created_by bigint REFERENCES usuarios(id), created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_logistica_remisiones_tenant ON logistica_remisiones(empresa_id,fecha DESC,estado);
CREATE INDEX IF NOT EXISTS idx_logistica_remision_items_remision ON logistica_remision_items(remision_id);
CREATE INDEX IF NOT EXISTS idx_logistica_movimientos_tenant ON logistica_movimientos(empresa_id,created_at DESC);
